  ctx.setLineDash([5, 4]);
  poly(ctx, diamondPoints(b.x, b.y, 1, 1, .11), null, color, 1.4);
  ctx.restore();
  // diagonal tint stripes
  ctx.save();
  ctx.beginPath(); poly(ctx, diamondPoints(b.x, b.y, 1, 1, .08), null); ctx.clip();
  ctx.globalAlpha = .1;
  for (let i = -1; i < 5; i++) {
    const t = i * .28;
    line(ctx, iso(b.x + t, b.y), iso(b.x + t + .5, b.y + 1), color, 2);
  }
  ctx.restore();
