+        ctx.beginPath(); ctx.arc(c.x + bx * s + sway, c.y + by * s, br * s, 0, 7); ctx.fill();
+      }
+      ctx.fillStyle = 'rgba(140,220,130,.28)';
+      ctx.beginPath(); ctx.arc(c.x - 5 * s + sway, c.y - 27 * s, 5 * s, 0, 7); ctx.fill();
+    }
+  }
+  function drawTree(ctx, b, def, time) {
