+    const c = iso(gx, gy);
+    ellipse(ctx, c.x, c.y + 1, 5 * s, 2 * s, 'rgba(20,50,35,.18)');
+    line(ctx, { x: c.x, y: c.y }, { x: c.x, y: c.y - 27 * s }, '#6d7c78', 1.8 * s);
+    line(ctx, { x: c.x, y: c.y - 27 * s }, { x: c.x + 6 * s, y: c.y - 29 * s }, '#6d7c78', 1.4 * s);
