+  function kindOf(def) { return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i'; }
+
+  function checkUnlocks(silent) {
+    if (!state) return;
+    for (const id in DEFS) {
+      const d = DEFS[id];
