+        state.money += m.reward;
+        sfx.reward();
+        toast(`Misi selesai: ${m.label} · +${money(m.reward)}`, 'reward', 'trophy');
+        if (m.id === 'metro' && !state.won) {
+          state.won = true;
+          setTimeout(showWin, 900);
