+    }
+  }
+  function happyLabel(v) {
+    if (v >= 85) return 'Sangat bahagia';
+    if (v >= 70) return 'Bahagia';
+    if (v >= 55) return 'Cukup senang';
+    if (v >= 40) return 'Biasa saja';
