+    else if (d.waterSupply) rows = `<span>+${d.waterSupply} air</span><span>Biaya ${money(d.maint)}/mg</span>`;
+    else if (d.jobs) rows = `<span>${d.jobs} pekerjaan</span><span>Biaya ${money(d.maint)}/mg</span>`;
